#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(optparse); library(jsonlite); library(ggplot2)})
`%||%` <- function(a,b) if (is.null(a)) b else a
op <- parse_args(OptionParser(option_list=list(make_option('--input',type='character'),make_option('--params',type='character'),make_option('--output',type='character'))))
out <- op$output %||% getwd(); dir.create(out,recursive=TRUE,showWarnings=FALSE)
logmsg <- function(x) cat(sprintf('[%s] %s\n',format(Sys.time(),'%F %T'),x),file=file.path(out,'run.log'),append=TRUE)
fail <- function(m,d='',s='Check the input columns and params.json.') { write(toJSON(list(error=m,detail=d,suggestion=s),auto_unbox=TRUE,pretty=TRUE),file.path(out,'error.json')); quit(status=1) }
tryCatch({
  if(is.null(op$input)||!file.exists(op$input)) fail('Input file not found',as.character(op$input))
  p <- if(!is.null(op$params)&&file.exists(op$params)) fromJSON(op$params,simplifyVector=FALSE) else list()
  val <- function(n,d=NULL,aliases=character()) { x<-p[[n]]; if(is.null(x)) for(g in names(p)) if(is.list(p[[g]])&&!is.null(p[[g]][[n]])){x<-p[[g]][[n]];break}; if(is.null(x)) for(a in aliases) if(!is.null(p[[a]])){x<-p[[a]];break}; if(is.null(x)) d else x }
  vec <- function(x) if(is.null(x)) character() else trimws(as.character(unlist(x)))
  num <- function(n,d=0,aliases=character()) { x<-suppressWarnings(as.numeric(unlist(val(n,d,aliases))[1]));if(is.na(x))d else x }
  boo <- function(n,d=FALSE,aliases=character()) { x<-val(n,d,aliases);if(is.logical(x))isTRUE(x[1])else tolower(as.character(x[1]))%in%c('true','1','yes','y','on') }
  readtab <- function(f) if(tolower(tools::file_ext(f))%in%c('tsv','txt'))read.delim(f,check.names=FALSE,stringsAsFactors=FALSE)else read.csv(f,check.names=FALSE,stringsAsFactors=FALSE)
  d<-readtab(op$input);cn<-names(d);lower<-tolower(cn)
  findcol <- function(x,defs=character(),req=TRUE){z<-c(x,defs);i<-match(tolower(z),lower);i<-i[!is.na(i)];if(length(i))cn[i[1]]else if(req)fail('Required column not found',paste(z,collapse=', '))else NULL}
  cc<-findcol(val('category_column',NULL,c('category_col','x_column','label_col')),c('category','name','label','term','id'));gc<-findcol(val('group_column',NULL,c('group_col')),c('group','class','type'),FALSE);lc<-findcol(val('label_column',NULL,c('label_col')),character(),FALSE);colorc<-findcol(val('color_column',NULL,c('color_col','fill_column')),character(),FALSE);vc<-findcol(val('value_column',NULL,c('value_col','numeric_column','y_column')),character(),FALSE)
  if(is.null(vc)){candidates<-cn[vapply(d,is.numeric,logical(1))];candidates<-setdiff(candidates,c(cc,gc,lc,colorc));if(!length(candidates))fail('No numeric value column found');vc<-candidates[1]}
  original<-d;inc<-vec(val('rows_include'));exc<-vec(val('rows_exclude'));ci<-vec(val('categories_include'));ce<-vec(val('categories_exclude'));keep<-rep(TRUE,nrow(d));if(length(inc))keep<-seq_len(nrow(d))%in%suppressWarnings(as.integer(inc))|as.character(d[[cc]])%in%inc;if(length(exc))keep<-keep&!(seq_len(nrow(d))%in%suppressWarnings(as.integer(exc))|as.character(d[[cc]])%in%exc);if(length(ci))keep<-keep&as.character(d[[cc]])%in%ci;if(length(ce))keep<-keep&!as.character(d[[cc]])%in%ce;d<-d[keep,,drop=FALSE];if(length(inc)||length(exc)||length(ci)||length(ce))write.csv(original[keep,,drop=FALSE],file.path(out,'selected_rows.csv'),row.names=FALSE)
  z<-data.frame(category=as.character(d[[cc]]),value=suppressWarnings(as.numeric(d[[vc]])),stringsAsFactors=FALSE);z$group<-if(is.null(gc))''else as.character(d[[gc]]);z$label<-if(is.null(lc))z$category else as.character(d[[lc]]);z$color<-if(is.null(colorc))NA_character_ else as.character(d[[colorc]]);z<-z[!is.na(z$value)&nzchar(z$category),,drop=FALSE];if(!nrow(z))fail('No valid numeric rows remain')
  if(length(ci))z<-z[z$category%in%ci,,drop=FALSE];if(length(ce))z<-z[!z$category%in%ce,,drop=FALSE];if(!nrow(z))fail('No rows remain after filtering')
  keys<-c('category','group');agg<-aggregate(value~category+group,z,sum);labs<-aggregate(label~category+group,z,function(x)x[1]);cols<-aggregate(color~category+group,z,function(x){x<-x[nzchar(x)];if(length(x))x[1]else NA_character_});z<-merge(merge(agg,labs,by=keys,sort=FALSE),cols,by=keys,sort=FALSE);z$label<-ifelse(nzchar(z$label),z$label,ifelse(nzchar(z$group),paste(z$category,z$group,sep=': '),z$category))
  neg<-tolower(as.character(val('negative_value_policy','exclude')));if(neg%in%c('exclude','drop'))z<-z[z$value>0,,drop=FALSE]else if(neg%in%c('absolute','abs'))z$value<-abs(z$value)else if(neg%in%c('zero','clamp'))z$value<-pmax(z$value,0);if(!nrow(z)||sum(z$value)<=0)fail('Values must contain a positive total after negative_value_policy')
  so<-tolower(as.character(val('sort','none')));sd<-tolower(as.character(val('sort_direction','descending')));if(so%in%c('value','ascending','descending'))z<-z[order(z$value,decreasing=sd!='ascending'),,drop=FALSE];if(so%in%c('category','name'))z<-z[order(z$category,decreasing=sd=='descending'),,drop=FALSE];top<-as.integer(num('top_n',0));if(top>0)z<-z[seq_len(min(top,nrow(z))),,drop=FALSE]
  z$percent<-z$value/sum(z$value);mode<-tolower(as.character(val('mode','pie')));hole<-boo('hole_show',mode=='donut');radius<-max(0,min(.99,num('inner_radius',0,c('hollow_size'))));if(!hole)radius<-0
  z$explode<-0;ex<-val('explode',NULL);if(!is.null(ex)){ex<-as.numeric(unlist(ex));if(length(ex)==1)z$explode<-ex else z$explode<-ex[seq_len(min(length(ex),nrow(z)))]};z$explode<-pmax(0,z$explode)*max(0,num('explode_amount',0))
  palette<-c('#4E79A7','#F28E2B','#E15759','#76B7B2','#59A14F','#EDC948','#B07AA1','#FF9DA7','#9C755F','#BAB0AC');pal<-val('custom_colors',NULL);if(is.null(pal))pal<-val('palette',NULL);if(!is.null(pal)){u<-unlist(pal);if(length(u))palette<-as.character(u)};cmap<-val('color_map',NULL);if(!is.null(cmap)){u<-unlist(cmap);if(!is.null(names(u)))palette<-c(palette,setNames(as.character(u),names(u)))};z$fill<-ifelse(nzchar(z$color),z$color,unname(palette[(seq_len(nrow(z))-1)%%length(palette)+1]));if(!is.null(names(palette)))z$fill<-ifelse(!is.na(palette[z$label]),unname(palette[z$label]),z$fill);write.csv(z,file.path(out,'pie_data_used.csv'),row.names=FALSE)
  w<-num('width',8);h<-num('height',6);dpi<-num('dpi',300);bg<-as.character(val('panel_background','#FFFFFF'));hf<-as.character(val('hole_fill',bg));xring<-if(radius>0)(1+radius)/2 else .5
  q<-ggplot(z,aes(x=xring,y=value,fill=label))+geom_col(width=if(radius>0)1-radius else 1,colour=val('stroke_color','#FFFFFF'),linewidth=num('stroke_width',.5),alpha=num('fill_alpha',1));if(radius>0)q<-q+geom_col(data=data.frame(x=radius/2,y=sum(z$value)),aes(x=x,y=y),inherit.aes=FALSE,width=radius,fill=hf,colour=val('hole_border_color','#FFFFFF'),linewidth=num('hole_border_width',0))
  lm<-tolower(as.character(val('label_mode','percent')));lab<-if(lm=='name')z$label else if(lm=='value')formatC(z$value,format='fg',digits=num('value_digits',3))else if(lm=='name_value')paste0(z$label,': ',formatC(z$value,format='fg',digits=num('value_digits',3)))else if(lm=='name_percent')paste0(z$label,' (',round(z$percent*100,1),'%)')else paste0(round(z$percent*100,1),'%');if(boo('label_show',TRUE))q<-q+geom_text(aes(label=lab),position=position_stack(vjust=.5),size=num('label_size',3),colour=val('label_color','#222222'),family=val('label_family','sans'),fontface=val('label_face','plain'));if(radius>0&&boo('hole_label_show',FALSE))q<-q+annotate('text',x=radius/2,y=sum(z$value)/2,label=val('hole_label',''),size=num('hole_label_size',5)/ggplot2::.pt,colour=val('hole_label_color','#222222'),family=val('hole_label_family','sans'),fontface=val('hole_label_face','plain'))
  clockwise<-tolower(as.character(val('direction',if(boo('clockwise',TRUE))'clockwise'else'counterclockwise')))%in%c('clockwise','cw');q<-q+coord_polar(theta='y',start=num('start_angle',0)*pi/180,direction=if(clockwise)-1 else 1)+xlim(0,1)+labs(title=if(boo('title_show',TRUE))val('title',NULL)else NULL,subtitle=val('subtitle',NULL),caption=val('caption',NULL),fill=val('legend_title',''))+theme_void(base_family=val('label_family','sans'))+theme(plot.background=element_rect(fill=val('background_color',bg),colour=NA),panel.background=element_rect(fill=bg,colour=NA),legend.position=if(boo('legend_show',TRUE))val('legend_position','right')else'none',legend.direction=val('legend_direction','vertical'),legend.text=element_text(size=num('legend_text_size',9)),legend.title=element_text(size=num('legend_title_size',10)),plot.title=element_text(size=num('title_size',16),colour=val('title_color','#222222'),face=val('title_face','bold'),hjust=num('title_hjust',0)))
  ggsave(file.path(out,'result.svg'),q,width=w,height=h,units='in',dpi=dpi);ggsave(file.path(out,'result.pdf'),q,width=w,height=h,units='in');ggsave(file.path(out,'result.png'),q,width=w,height=h,units='in',dpi=dpi)
  if(requireNamespace('plotly',quietly=TRUE)&&requireNamespace('htmlwidgets',quietly=TRUE)){hover<-paste0(z$label,'<br>Value: ',z$value,'<br>Percent: ',round(z$percent*100,2),'%');pl<-plotly::plot_ly(labels=z$label,values=z$value,type='pie',hole=radius,marker=list(colors=z$fill,line=list(color=val('stroke_color','#FFFFFF'),width=num('stroke_width',1))),text=lab,hovertext=hover,hoverinfo='text',sort=FALSE,rotation=num('start_angle',0),direction=if(clockwise)'clockwise'else'counterclockwise',pull=z$explode);pl<-plotly::layout(pl,title=list(text=if(boo('title_show',TRUE))val('title','')else''),showlegend=boo('legend_show',TRUE),paper_bgcolor=val('background_color',bg),plot_bgcolor=bg);if(radius>0&&boo('hole_label_show',FALSE))pl<-plotly::layout(pl,annotations=list(list(text=val('hole_label',''),x=num('hole_label_x',.5),y=num('hole_label_y',.5),showarrow=FALSE,font=list(size=num('hole_label_size',16),color=val('hole_label_color','#222222')))));pl<-plotly::config(pl,displaylogo=FALSE,scrollZoom=boo('zoom',TRUE),doubleClick='reset',modeBarButtonsToAdd=if(boo('lasso_select',TRUE))c('lasso2d','select2d')else if(boo('selectable',TRUE))'select2d'else character());htmlwidgets::saveWidget(pl,file.path(out,'result.html'),selfcontained=TRUE)}else writeLines('<html><body>Plotly is unavailable.</body></html>',file.path(out,'result.html'))
  meta<-list(plugin='interactive_pie_plot',mode=mode,hole_show=hole,inner_radius=radius,rows=nrow(z),categories=as.character(z$label),outputs=c('result.svg','result.pdf','result.png','result.html','figure.json','run.log','pie_data_used.csv'));write(toJSON(meta,auto_unbox=TRUE,pretty=TRUE),file.path(out,'figure.json'));if(file.exists(file.path(out,'error.json')))unlink(file.path(out,'error.json'));logmsg(sprintf('Rendered %d slices; effective inner_radius %.3f',nrow(z),radius))
},error=function(e)fail('Plot generation failed',conditionMessage(e)))
